Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetShipmentsAsync(string? statusFilter = null)
    {
        var query = db.Shipments.AsQueryable();

        if (!string.IsNullOrEmpty(statusFilter) && Enum.TryParse<Data.ShipmentStatus>(statusFilter, true, out var status))
        {
            query = query.Where(s => s.Status == status);
        }

        return await query
            .OrderByDescending(s => s.CreatedAtUtc)
            .Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = (Client.Models.ShipmentStatus)(int)s.Status,
                CreatedAtUtc = s.CreatedAtUtc,
                EstimatedDeliveryUtc = s.EstimatedDeliveryUtc,
                RecipientName = s.RecipientName
            })
            .ToListAsync();
    }

    public async Task<ShipmentSummary?> TrackShipmentAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

        if (shipment is null) return null;

        return new ShipmentSummary
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = (Client.Models.ShipmentStatus)(int)shipment.Status,
            CreatedAtUtc = shipment.CreatedAtUtc,
            EstimatedDeliveryUtc = shipment.EstimatedDeliveryUtc,
            RecipientName = shipment.RecipientName
        };
    }

    public async Task<ShipmentSummary> UpdateStatusAsync(int id, Client.Models.ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id)
            ?? throw new KeyNotFoundException($"Shipment {id} not found.");

        shipment.Status = (Data.ShipmentStatus)(int)newStatus;

        await db.SaveChangesAsync();

        return new ShipmentSummary
        {
            Id = shipment.Id,
            TrackingNumber = shipment.TrackingNumber,
            Origin = shipment.Origin,
            Destination = shipment.Destination,
            Status = newStatus,
            CreatedAtUtc = shipment.CreatedAtUtc,
            EstimatedDeliveryUtc = shipment.EstimatedDeliveryUtc,
            RecipientName = shipment.RecipientName
        };
    }
}
```

