                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-1001)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isSearching">
                        @if (isSearching)
                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Track
                    </button>
                </div>

                @if (searchPerformed && shipment is null)
                {
                    <div class="alert alert-warning mt-3 mb-0">
                        No shipment found with tracking number "<strong>@searchedNumber</strong>".
                    </div>
                }

                @if (shipment is not null)
                {
                    <div class="card mt-3">
                        <div class="card-body">
                            <h6>@shipment.TrackingNumber</h6>
                            <p class="mb-1"><strong>Status:</strong> <span class="badge @GetStatusBadge(shipment.Status)">@shipment.Status</span></p>
                            <p class="mb-1"><strong>From:</strong> @shipment.Origin</p>
                            <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                            <p class="mb-1"><strong>Recipient:</strong> @(shipment.RecipientName ?? "N/A")</p>
                            @if (shipment.EstimatedDeliveryUtc.HasValue)
                            {
                                <p class="mb-0"><strong>Estimated Delivery:</strong> @shipment.EstimatedDeliveryUtc.Value.ToString("MMMM dd, yyyy")</p>
                            }
                        </div>
                    </div>
                }
            </div>
        </div>
    </div>
</div>

@code {
    private string trackingNumber = string.Empty;
    private string searchedNumber = string.Empty;
    private ShipmentSummary? shipment;
    private bool isSearching;
    private bool searchPerformed;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchPerformed = false;
        shipment = null;

        try
        {
            searchedNumber = trackingNumber.Trim();
            shipment = await ShipmentService.TrackShipmentAsync(searchedNumber);
            searchPerformed = true;
        }
        finally
        {
            isSearching = false;
        }
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

