using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;

namespace ShipmentTracker.Data;

public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
        });
    }
}

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddScoped<ShipmentTracker.Client.Services.IShipmentService, ShipmentTracker.Services.ShipmentServerService>();

var app = builder.Build();

using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    await SeedData.InitializeAsync(db);
}

// Shipment API endpoints
var shipments = app.MapGroup("/api/shipments").RequireAuthorization();

shipments.MapGet("/", async (string? status, ShipmentTracker.Client.Services.IShipmentService service) =>
    Results.Ok(await service.GetShipmentsAsync(status)));

shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, ShipmentTracker.Client.Services.IShipmentService service) =>
{
    var result = await service.TrackShipmentAsync(trackingNumber);
    return result is not null ? Results.Ok(result) : Results.NotFound();
}).AllowAnonymous();

shipments.MapPut("/{id:int}/status", async (int id, ShipmentTracker.Client.Models.ShipmentStatus newStatus, ShipmentTracker.Client.Services.IShipmentService service) =>
{
    try
    {
        var result = await service.UpdateStatusAsync(id, newStatus);
        return Results.Ok(result);
    }
    catch (KeyNotFoundException)
    {
        return Results.NotFound();
    }
}).RequireAuthorization();

app.Run();

