                        {
                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        }
                        Track
                    </button>
                </div>

                @if (searchPerformed && shipment is null)
                {
                    <div class="alert alert-warning mt-3 mb-0">
