61.     private string trackingNumber = string.Empty;
62.     private string searchedNumber = string.Empty;
63.     private ShipmentSummary? shipment;
64.     private bool isSearching;
65.     private bool searchPerformed;
66. 
67.     private async Task TrackShipment()
68.     {
69.         if (string.IsNullOrWhiteSpace(trackingNumber)) return;
70. 
71.         isSearching = true;
72.         searchPerformed = false;
73.         shipment = null;
74. 
75.         try
76.         {
77.             searchedNumber = trackingNumber.Trim();
78.             shipment = await ShipmentService.TrackShipmentAsync(searchedNumber);
79.             searchPerformed = true;
80.         }
81.         finally
82.         {
83.             isSearching = false;
84.         }
85.     }
86. 
87.     private async Task HandleKeyDown(KeyboardEventArgs e)
88.     {
89.         if (e.Key == "Enter")
90.             await TrackShipment();
91.     }
