94.     {
95.         ShipmentStatus.Pending => "bg-secondary",
96.         ShipmentStatus.PickedUp => "bg-info text-dark",
97.         ShipmentStatus.InTransit => "bg-primary",
98.         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
99.         ShipmentStatus.Delivered => "bg-success",
