 @page "/shipments"
 @using Microsoft.AspNetCore.Authorization
 @using ShipmentTracker.Client.Models
 @using ShipmentTracker.Client.Services
 @attribute [Authorize]
 @inject IShipmentService ShipmentService

 <PageTitle>Shipments - ShipmentTracker</PageTitle>

 <h2>📋 Shipment Dashboard</h2>

 <div class="row mb-3">
     <div class="col-md-4">
         <label class="form-label">Filter by status</label>
         <select class="form-select" @bind="selectedStatus" @bind:after="LoadShipments">
             <option value="">All</option>
             @foreach (var status in Enum.GetValues<ShipmentStatus>())
             {
                 <option value="@status">@status</option>
             }
         </select>
     </div>
 </div>

 @if (isLoading)
 {
     <div class="d-flex align-items-center">
         <div class="spinner-border spinner-border-sm me-2" role="status"></div>
         <span>Loading shipments…</span>
     </div>
 }
 else if (shipments is null || shipments.Count == 0)
 {
     <div class="alert alert-info">No shipments found.</div>
 }
 else
 {
     <div class="table-responsive">
         <table class="table table-striped table-hover">
             <thead class="table-dark">
                 <tr>
                     <th>Tracking #</th>
                     <th>Recipient</th>
                     <th>Origin</th>
                     <th>Destination</th>
                     <th>Status</th>
                     <th>Est. Delivery</th>
                     <th>Actions</th>
                 </tr>
             </thead>
             <tbody>
                 @foreach (var s in shipments)
                 {
                     <tr>
                         <td><strong>@s.TrackingNumber</strong></td>
                         <td>@(s.RecipientName ?? "—")</td>
                         <td>@s.Origin</td>
                         <td>@s.Destination</td>
                         <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                         <td>@(s.EstimatedDeliveryUtc?.ToString("MMM dd, yyyy") ?? "—")</td>
                         <td>
                             @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Cancelled)
                             {
                                 <div class="btn-group btn-group-sm">
                                     <select class="form-select form-select-sm" style="width: auto"
                                             @onchange="(e) => UpdateStatus(s, e)">
                                         <option value="" selected disabled>Update…</option>
                                         @foreach (var status in GetNextStatuses(s.Status))
                                         {
                                             <option value="@((int)status)">@status</option>
                                         }
                                     </select>
                                 </div>
                             }
                         </td>
                     </tr>
                 }
             </tbody>
         </table>
     </div>
 }

 @code {
     private List<ShipmentSummary>? shipments;
     private string selectedStatus = string.Empty;
     private bool isLoading = true;

     protected override async Task OnInitializedAsync()
     {
         await LoadShipments();
     }

     private async Task LoadShipments()
     {
         isLoading = true;
         try
         {
             shipments = await ShipmentService.GetShipmentsAsync(
                 string.IsNullOrEmpty(selectedStatus) ? null : selectedStatus);
         }
         finally
         {
             isLoading = false;
         }
     }

     private async Task UpdateStatus(ShipmentSummary shipment, ChangeEventArgs e)
     {
         if (e.Value is string val && int.TryParse(val, out var statusInt))
         {
             var newStatus = (ShipmentStatus)statusInt;
             var updated = await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
             shipment.Status = updated.Status;
         }
     }

     private static ShipmentStatus[] GetNextStatuses(ShipmentStatus current) => current switch
     {
         ShipmentStatus.Pending => [ShipmentStatus.PickedUp, ShipmentStatus.Cancelled],
         ShipmentStatus.PickedUp => [ShipmentStatus.InTransit, ShipmentStatus.Cancelled],
         ShipmentStatus.InTransit => [ShipmentStatus.OutForDelivery, ShipmentStatus.Cancelled],
         ShipmentStatus.OutForDelivery => [ShipmentStatus.Delivered],
         _ => []
     };

     private static string GetStatusBadge(ShipmentStatus status) => status switch
     {
         ShipmentStatus.Pending => "bg-secondary",
         ShipmentStatus.PickedUp => "bg-info text-dark",
         ShipmentStatus.InTransit => "bg-primary",
         ShipmentStatus.OutForDelivery => "bg-warning text-dark",
         ShipmentStatus.Delivered => "bg-success",
         ShipmentStatus.Cancelled => "bg-danger",
         _ => "bg-secondary"
     };
 }
